1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
46	  values.reduce((sum, value) => sum + amountOf(value), 0);
47	
48	const BASE_PREMIUM_BY_ITEM_TYPE = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	} as const satisfies Record<string, number>;
56	
57	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
58	
59	const BLOCK_SIZE = 3;
60	const BLOCK_BASE_PREMIUM = 60;
61	const CURSE_SURCHARGE_PERCENT = 50;
62	const HIGH_ENCHANTMENT_THRESHOLD = 5;
63	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
64	const LOYALTY_THRESHOLD_YEARS = 2;
65	const LOYALTY_DISCOUNT_PERCENT = 20;
66	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
67	
68	const basePremiumOf = (item: Item): number =>
69	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
70	
71	interface RiskSurcharge {
72	  appliesTo: (item: Item) => boolean;
73	  percent: number;
74	}
75	
76	const RISK_SURCHARGES: RiskSurcharge[] = [
77	  { appliesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
78	  {
79	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
80	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
81	  },
82	];
83	
84	const itemSurcharge = (item: Item): number =>
85	  sumOf(
86	    RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)),
87	    (surcharge) => percentOf(basePremiumOf(item), surcharge.percent),
88	  );
89	
90	const policySurcharges = (items: Item[]): number => sumOf(items, itemSurcharge);
91	
92	const groupByType = (items: Item[]): Item[][] => [
93	  ...items
94	    .reduce(
95	      (groups, item) =>
96	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
97	      new Map<string, Item[]>(),
98	    )
99	    .values(),
100	];
101	
102	const basePremiumOfGroup = (group: Item[]): number =>
103	  group.length === BLOCK_SIZE
104	    ? BLOCK_BASE_PREMIUM
105	    : sumOf(group, basePremiumOf);
106	
107	const policyBasePremium = (items: Item[]): number =>
108	  sumOf(groupByType(items), basePremiumOfGroup);
109	
110	interface QuoteContext {
111	  customer: Customer;
112	  previousQuotes: number;
113	}
114	
115	const isLoyal = ({ customer }: QuoteContext): boolean =>
116	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
117	
118	const isFollowUpContract = ({ previousQuotes }: QuoteContext): boolean =>
119	  previousQuotes > 0;
120	
121	interface PolicyAdjustment {
122	  appliesTo: (context: QuoteContext) => boolean;
123	  percent: number;
124	}
125	
126	const POLICY_ADJUSTMENTS: PolicyAdjustment[] = [
127	  { appliesTo: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
128	  { appliesTo: isLoyal, percent: -LOYALTY_DISCOUNT_PERCENT },
129	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
130	];
131	
132	const policyAdjustments = (policyBase: number, context: QuoteContext): number =>
133	  sumOf(
134	    POLICY_ADJUSTMENTS.filter((adjustment) => adjustment.appliesTo(context)),
135	    (adjustment) => percentOf(policyBase, adjustment.percent),
136	  );
137	
138	const quotePremium = (items: Item[], context: QuoteContext): number => {
139	  const policyBase = policyBasePremium(items);
140	  const premiumBeforeFee =
141	    policyBase + policySurcharges(items) + policyAdjustments(policyBase, context);
142	  return Math.ceil(premiumBeforeFee + PROCESSING_FEE);
143	};
144	
145	const INSURANCE_VALUE_BY_ITEM_TYPE = {
146	  sword: 1000,
147	  amulet: 600,
148	  staff: 800,
149	  potion: 400,
150	  rune: 250,
151	  moonstone: 250,
152	} as const satisfies Record<InsurableItemType, number>;
153	
154	const DEDUCTIBLE_PER_DAMAGE = 100;
155	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
156	
157	const insuranceValueOf = (item: Item): number =>
158	  INSURANCE_VALUE_BY_ITEM_TYPE[item.type as InsurableItemType];
159	
160	const policyCapOf = (items: Item[]): number =>
161	  CAP_MULTIPLE_OF_INSURANCE_SUM * sumOf(items, insuranceValueOf);
162	
163	const REIMBURSABLE_ENCHANTMENT_THRESHOLD = 8;
164	const REDUCED_REIMBURSEMENT_PERCENT = 50;
165	
166	const reimbursementFor = (damage: Damage, insured: Item[]): number => {
167	  const item = insured.find(({ type }) => type === damage.itemType);
168	  const covered =
169	    (item?.enchantment ?? 0) >= REIMBURSABLE_ENCHANTMENT_THRESHOLD
170	      ? percentOf(damage.amount, REDUCED_REIMBURSEMENT_PERCENT)
171	      : damage.amount;
172	  return covered - DEDUCTIBLE_PER_DAMAGE;
173	};
174	
175	const policyOf = (step: Extract<Step, { op: "claim" }>, steps: Step[]) => {
176	  const policy = steps[step.policy];
177	  if (policy?.op !== "quote") throw new Error("claim references no policy");
178	  return policy;
179	};
180	
181	const claimResult = (
182	  step: Extract<Step, { op: "claim" }>,
183	  steps: Step[],
184	): StepResult => {
185	  const insured = policyOf(step, steps).items;
186	  const payout = sumOf(step.incident.damages, (damage) =>
187	    reimbursementFor(damage, insured),
188	  );
189	  return { payout, remainingCap: policyCapOf(insured) - payout };
190	};
191	
192	const runStep = (
193	  step: Step,
194	  context: QuoteContext,
195	  steps: Step[],
196	): StepResult =>
197	  step.op === "quote"
198	    ? { premium: quotePremium(step.items, context) }
199	    : claimResult(step, steps);
200	
201	const countQuotesBefore = (steps: Step[], index: number): number =>
202	  steps.slice(0, index).filter((step) => step.op === "quote").length;
203	
204	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
205	  results: steps.map((step, index) =>
206	    runStep(
207	      step,
208	      { customer, previousQuotes: countQuotesBefore(steps, index) },
209	      steps,
210	    ),
211	  ),
212	});
